-- Complete repository object inventory plus material catalog invariants. No data writes.
do $$
declare missing text;
begin
 select string_agg(name,', ') into missing from unnest(array['public.audit_logs','public.batches','public.branch_memberships','public.branches','public.categories','public.customers','public.expiry_actions','public.expiry_alerts','public.expiry_policies','public.expiry_risk','public.import_jobs','public.import_rows','public.inventory_balances','public.inventory_movements','public.inventory_stock_count_lines','public.inventory_stock_counts','public.manufacturers','public.notification_preferences','public.notifications','public.organization_memberships','public.organization_settings','public.organizations','public.payments','public.permissions','public.product_barcodes','public.products','public.profiles','public.purchase_order_lines','public.purchase_orders','public.purchase_receipt_lines','public.purchase_receipts','public.report_daily_sales','public.report_expiry_status_summary','public.report_inventory_value','public.report_purchasing_summary','public.report_transfer_summary','public.role_permissions','public.roles','public.sale_items','public.sale_refund_items','public.sale_refunds','public.sales','public.staff_invitations','public.stock_transfer_lines','public.stock_transfers','public.subscription_plans','public.subscriptions','public.suppliers']) name where to_regclass(name) is null;
 if missing is not null then raise exception 'Missing relations: %',missing; end if;
 select string_agg(name,', ') into missing from unnest(array['app_private.accept_staff_invitation','app_private.acknowledge_expiry_alert_impl','app_private.approve_stock_transfer_impl','app_private.assert_inventory_movement_safe','app_private.audit_catalog_change','app_private.audit_completed_inventory_count','app_private.audit_security_change','app_private.cancel_staff_invitation','app_private.cancel_stock_transfer_impl','app_private.complete_owner_setup','app_private.complete_sale_impl','app_private.complete_sale_reviewed_impl','app_private.complete_sale_with_customer_impl','app_private.create_branch_with_access','app_private.create_purchase_order_impl','app_private.create_stock_transfer_impl','app_private.current_role_code','app_private.dispatch_stock_transfer_impl','app_private.dispose_batch_impl','app_private.guard_product_stock_unit','app_private.has_branch_access','app_private.has_permission','app_private.inventory_lock_key','app_private.invite_staff','app_private.is_org_member','app_private.lock_business_currency','app_private.lock_movement_stock_unit','app_private.maintain_staff_access','app_private.my_membership_unavailable','app_private.my_staff_invitations','app_private.notification_visible','app_private.notify_expiry_alert','app_private.owner_setup_progress','app_private.prevent_audit_mutation','app_private.prevent_inventory_movement_mutation','app_private.receive_purchase_order_impl','app_private.receive_stock_transfer_impl','app_private.record_expiry_action_impl','app_private.refresh_expiry_alerts_impl','app_private.refresh_operational_notifications_impl','app_private.refund_sale_impl','app_private.require_positive_selling_price','app_private.return_batch_to_supplier_impl','app_private.role_is_assignable','app_private.staff_directory_details','app_private.validate_business_configuration','public.accept_staff_invitation','public.acknowledge_expiry_alert','public.approve_stock_transfer','public.cancel_staff_invitation','public.cancel_stock_transfer','public.check_import_row','public.commit_import_job','public.complete_inventory_stock_count','public.complete_owner_setup','public.complete_sale','public.complete_sale_with_customer','public.create_branch_with_access','public.create_catalog_product','public.create_product_with_barcode','public.create_purchase_order','public.create_stock_transfer','public.dispatch_stock_transfer','public.dispose_batch','public.get_fefo_batches','public.handle_new_auth_user','public.invite_staff','public.list_stock_transfer_destinations','public.maintain_product_barcode','public.maintain_staff_access','public.my_membership_unavailable','public.my_staff_invitations','public.owner_setup_progress','public.post_inventory_movement','public.post_opening_stock','public.preview_import_rows','public.quote_sale','public.read_operational_report','public.read_stock_transfer_context','public.receive_purchase_order','public.receive_stock_transfer','public.record_expiry_action','public.refresh_expiry_alerts','public.refresh_operational_notifications','public.refund_sale','public.return_batch_to_supplier','public.search_catalog_batches','public.search_catalog_products','public.search_inventory_stock','public.set_updated_at','public.staff_directory_details','public.stage_import_job']) name where not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname||'.'||p.proname=name);
 if missing is not null then raise exception 'Missing function names: %',missing; end if;
 -- RBAC hardening lines 310-312 intentionally DROP the exposed helpers.
 if to_regprocedure('public.is_org_member(uuid)') is not null
 or to_regprocedure('public.has_branch_access(uuid)') is not null
 or to_regprocedure('public.has_permission(uuid,text)') is not null then
   raise exception 'Deprecated exposed RBAC helpers must be absent';
 end if;
 if to_regprocedure('app_private.is_org_member(uuid)') is null
 or to_regprocedure('app_private.has_branch_access(uuid)') is null
 or to_regprocedure('app_private.has_permission(uuid,text)') is null then
   raise exception 'Private RBAC replacements required';
 end if;
 if not exists(select 1 from pg_constraint where conrelid='public.branches'::regclass and conname='branches_organization_id_id_unique' and contype='u') then raise exception 'Missing tenant composite branch key'; end if;
 if exists(select 1 from pg_constraint c join pg_namespace n on n.oid=c.connamespace where n.nspname='public' and not c.convalidated) then raise exception 'Unvalidated constraints'; end if;
 if exists(select 1 from pg_index i join pg_class c on c.oid=i.indrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and (not i.indisvalid or not i.indisready)) then raise exception 'Invalid indexes'; end if;
 if not exists(select 1 from pg_trigger where tgrelid='public.inventory_movements'::regclass and tgname='inventory_movements_immutable' and tgenabled='O') then raise exception 'Missing ledger immutability trigger'; end if;
 if not exists(select 1 from pg_class where oid='public.inventory_movements'::regclass and relrowsecurity) then raise exception 'Ledger RLS disabled'; end if;
 raise notice 'PASS schema relations, function names, branch key, constraints, indexes, ledger trigger and RLS';
end $$;
